import { useContext, useState, useEffect, useCallback } from 'react';
import { AuthContext } from '../../context/authContext';
import './share.scss';
import Image from '../../assets/img.png';
import Map from '../../assets/map.png';
import Friend from '../../assets/friend.png';

const Share = () => {
  const { currentUser, accessToken } = useContext(AuthContext);
  const [description, setDescription] = useState('');
  const [file, setFile] = useState(null);
  const [filePreview, setFilePreview] = useState(null);
  const [location, setLocation] = useState('');
  const [friends, setFriends] = useState([]);
  const [taggedFriends, setTaggedFriends] = useState([]);
  const [showFriendsDropdown, setShowFriendsDropdown] = useState(false);
  const [error, setError] = useState(null);
  const [loading, setLoading] = useState(false);

  // Debug outputs
  useEffect(() => {
    console.log('Share: Current state:', { 
      description, 
      file: file ? { name: file.name, type: file.type, size: file.size } : null,
      location,
      taggedFriends,
      error,
      loading
    });
  }, [description, file, location, taggedFriends, error, loading]);

  const getProfilePictureUrl = (profilePicture) => {
    if (!profilePicture) {
      return 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
    }
    if (profilePicture.startsWith('http')) {
      return profilePicture;
    }
    const normalizedPath = profilePicture.replace(/^\/Uploads\//i, '/Uploads/');
    const url = `http://localhost:5000${normalizedPath}?t=${new Date().getTime()}`;
    return url;
  };

  // Fetch friends for tagging
  const fetchFriends = useCallback(async () => {
    if (!accessToken || !currentUser?._id) {
      console.log('Share: Missing token or user ID for fetching friends');
      return;
    }

    try {
      console.log(`Share: Fetching friends for user ID: ${currentUser._id}`);
      const res = await fetch(`http://localhost:5000/api/users/${currentUser._id}`, {
        headers: { Authorization: `Bearer ${accessToken}` },
      });

      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.message || `Failed to fetch friends: ${res.status}`);
      }

      const data = await res.json();
      console.log('Share: Fetched friends=', data.friends?.length || 0);
      setFriends(data.friends || []);
    } catch (err) {
      console.error('Share: Error fetching friends:', err.message);
      setError(`Failed to load friends: ${err.message}`);
    }
  }, [currentUser, accessToken]);

  useEffect(() => {
    if (currentUser && accessToken) {
      fetchFriends();
    }
  }, [currentUser, accessToken, fetchFriends]);

  // Handle file selection and preview
  useEffect(() => {
    if (file) {
      if (!(file instanceof File)) {
        setError('Invalid file object. Please select a valid image or video.');
        setFile(null);
        setFilePreview(null);
        return;
      }

      const fileType = file.type;
      const validTypes = ['image/jpeg', 'image/jpg', 'image/png', 'image/gif', 'video/mp4', 'video/quicktime'];

      if (!validTypes.includes(fileType)) {
        setError('Please select a valid image (JPEG, PNG, GIF) or video (MP4, MOV) file.');
        setFile(null);
        setFilePreview(null);
        return;
      }

      // Only check size for non-video files (images)
      if (fileType.startsWith('image/') && file.size > 500 * 1024) {
        setError('Image size exceeds 500KB limit.');
        setFile(null);
        setFilePreview(null);
        return;
      }

      if (file.size === 0) {
        setError('Selected file is empty. Please choose a valid file.');
        setFile(null);
        setFilePreview(null);
        return;
      }

      // Create preview
      const url = URL.createObjectURL(file);
      setFilePreview({ url, type: fileType.startsWith('image/') ? 'image' : 'video' });
      console.log('Share: File preview created:', { type: fileType, size: file.size });
    } else {
      setFilePreview(null);
    }

    return () => {
      if (filePreview?.url) {
        URL.revokeObjectURL(filePreview.url);
      }
    };
  }, [file]);

  // Toggle friend in taggedFriends
  const toggleFriendTag = (friendId) => {
    setTaggedFriends((prev) =>
      prev.includes(friendId)
        ? prev.filter((id) => id !== friendId)
        : [...prev, friendId]
    );
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    if (!description && !file && !location && taggedFriends.length === 0) {
      setError('Please provide a description, image/video, location, or tag friends.');
      return;
    }

    if (!accessToken) {
      setError('Authentication token is missing. Please log in again.');
      return;
    }

    if (!currentUser?._id) {
      setError('User ID is missing. Please log in again.');
      return;
    }

    setLoading(true);
    setError(null);

    try {
      console.log('Share: Creating post for user ID:', currentUser._id);

      let formData = new FormData();
      formData.append('userId', currentUser._id);
      formData.append('name', currentUser.name || '');
      formData.append('profilePicture', currentUser.profilePicture || '');
      formData.append('description', description || '');

      if (location) formData.append('location', location);

      if (taggedFriends.length > 0) {
        formData.append('taggedFriends', JSON.stringify(taggedFriends));
      }

      if (file) {
        formData.append('image', file);
        console.log('Share: Added file to FormData:', file.name, file.type, file.size);
      }

      // Log request details before sending
      console.log('Share: Sending request to create post with:', { 
        description, 
        hasFile: !!file,
        location,
        taggedFriends: taggedFriends.length
      });

      const res = await fetch('http://localhost:5000/api/posts', {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${accessToken}`
          // Don't set Content-Type header when using FormData - browser will set it automatically with boundary
        },
        body: formData,
      });

      // First check if response is OK
      if (!res.ok) {
        const errorData = await res.json();
        throw new Error(errorData.message || `Server returned ${res.status}`);
      }

      const data = await res.json();
      console.log('Share: Post created successfully:', data);

      // Reset form
      setDescription('');
      setFile(null);
      setFilePreview(null);
      setLocation('');
      setTaggedFriends([]);

      // Notify parent component about new post
      window.dispatchEvent(new Event('newPost'));

    } catch (err) {
      console.error('Share: Error creating post:', err.message);
      setError(`Failed to create post: ${err.message}`);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="share">
      <div className="container">
        <div className="top">
          <img
            src={getProfilePictureUrl(currentUser?.profilePicture)}
            alt={`${currentUser?.name}'s profile`}
            className="profile-img"
            onError={(e) => {
              e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
            }}
          />
          <input
            type="text"
            placeholder={`What's on your mind ${currentUser?.name || ''}?`}
            value={description}
            onChange={(e) => setDescription(e.target.value)}
            disabled={loading}
          />
        </div>
        {filePreview && (
          <div className="preview">
            {filePreview.type === 'image' ? (
              <img src={filePreview.url} alt="Preview" className="preview-media" />
            ) : (
              <video src={filePreview.url} controls className="preview-media" />
            )}
            <button
              className="remove-media"
              onClick={() => {
                setFile(null);
                setFilePreview(null);
              }}
            >
              Remove
            </button>
          </div>
        )}
        {location && (
          <div className="location">
            <span>Location: {location}</span>
            <button
              className="remove-location"
              onClick={() => setLocation('')}
            >
              Remove
            </button>
          </div>
        )}
        {taggedFriends.length > 0 && (
          <div className="tagged-friends">
            <span>
              Tagged:{' '}
              {taggedFriends
                .map((id) => friends.find((f) => f._id === id)?.name || 'Unknown')
                .join(', ')}
            </span>
            <button
              className="remove-tagged"
              onClick={() => setTaggedFriends([])}
            >
              Clear Tags
            </button>
          </div>
        )}
        <hr />
        <div className="bottom">
          <div className="left">
            <input
              type="file"
              id="file"
              accept="image/jpeg,image/jpg,image/png,image/gif,video/mp4,video/quicktime"
              style={{ display: 'none' }}
              onChange={(e) => {
                const selectedFile = e.target.files[0];
                if (selectedFile) {
                  console.log('Share: File selected:', {
                    name: selectedFile.name,
                    size: selectedFile.size,
                    type: selectedFile.type,
                  });
                  setFile(selectedFile);
                } else {
                  setFile(null);
                }
              }}
            />
            <label htmlFor="file">
              <div className="item">
                <img src={Image} alt="Add Media" />
                <span>Add Image/Video</span>
              </div>
            </label>
            <div className="item" onClick={() => {
              const loc = prompt('Enter location (e.g., New York, NY):');
              if (loc) setLocation(loc);
            }}>
              <img src={Map} alt="Add Place" />
              <span>Add Place</span>
            </div>
            <div className="item" onClick={() => setShowFriendsDropdown(!showFriendsDropdown)}>
              <img src={Friend} alt="Tag Friends" />
              <span>Tag Friends</span>
            </div>
            {showFriendsDropdown && (
              <div className="friends-dropdown">
                {friends.length > 0 ? (
                  friends.map((friend) => (
                    <div
                      key={friend._id}
                      className={`friend-option ${taggedFriends.includes(friend._id) ? 'selected' : ''}`}
                      onClick={() => toggleFriendTag(friend._id)}
                    >
                      <img
                        src={getProfilePictureUrl(friend.profilePicture)}
                        alt={`${friend.name}'s profile`}
                        className="friend-avatar"
                        onError={(e) => {
                          e.target.src = 'https://images.pexels.com/photos/3228727/pexels-photo-3228727.jpeg?auto=compress&cs=tinysrgb&w=1600';
                        }}
                      />
                      <span>{friend.name}</span>
                    </div>
                  ))
                ) : (
                  <p>No friends to tag.</p>
                )}
              </div>
            )}
          </div>
          <div className="right">
            <button onClick={handleSubmit} disabled={loading}>
              {loading ? 'Sharing...' : 'Share'}
            </button>
          </div>
        </div>
        {error && <p className="error">{error}</p>}
      </div>
    </div>
  );
};

export default Share;
